{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table maplemonk.beastlife_shiprocket_Query as WITH p AS ( SELECT * FROM maplemonk.Beastlife_db_Shiprocket_pickedup_ WHERE TRUE QUALIFY ROW_NUMBER() OVER ( PARTITION BY awb ORDER BY NULLIF(TRIM(picked_up_date), \'\') IS NULL, picked_up_date ) = 1 ), u AS ( SELECT * FROM `maplemonk.beastlife_unicommerce_fact_items` WHERE reference_code IS NOT NULL QUALIFY ROW_NUMBER() OVER ( PARTITION BY reference_code ORDER BY (shippingPackageStatus = \'CANCELLED\'), shippingPackageStatus ) = 1 ), d AS ( SELECT * FROM `maplemonk.D2C_master` WHERE TRUE QUALIFY ROW_NUMBER() OVER ( PARTITION BY ordeR_name ORDER BY Order_Date, order_time ) = 1 ), calendar AS ( SELECT PARSE_DATE(\'%Y-%m-%d\', event_date) AS event_date, Event, sub_event, FORMAT_DATE(\'%Y%m%d\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS DateAsInteger, FORMAT_DATE(\'%d\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS DateNumber, EXTRACT(YEAR FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) AS Year, FORMAT_DATE(\'%m\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS MonthNumber, FORMAT_DATE(\'%Y/%m\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS YearMonthNumber, FORMAT_DATE(\'%Y/%b\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS YearMonthShort, FORMAT_DATE(\'%b\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS MonthNameShort, FORMAT_DATE(\'%B\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS MonthNameLong, EXTRACT(DAYOFWEEK FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) AS DayOfWeekNumber, FORMAT_DATE(\'%A\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS DayOfWeek, FORMAT_DATE(\'%a\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS DayOfWeekShort, CONCAT(\'Q\', CAST(EXTRACT(QUARTER FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) AS STRING)) AS Quarter, CONCAT(FORMAT_DATE(\'%Y\', PARSE_DATE(\'%Y-%m-%d\', event_date)),\'/Q\', CAST(EXTRACT(QUARTER FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) AS STRING)) AS YearQuarter, CASE WHEN EXTRACT(DAY FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) BETWEEN 1 AND 7 THEN \'W1\' WHEN EXTRACT(DAY FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) BETWEEN 8 AND 14 THEN \'W2\' WHEN EXTRACT(DAY FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) BETWEEN 15 AND 21 THEN \'W3\' WHEN EXTRACT(DAY FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) BETWEEN 22 AND 28 THEN \'W4\' WHEN EXTRACT(DAY FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) >= 29 THEN \'W5\' END AS WeekPeriod FROM `beastlife-wh-474411.maplemonk.beastlife_db_Calender` ), catalog AS ( SELECT Category, SKU_Code, SKU_Type, Ingredients, Rev_Category, Sub_Category, Category_Type, Product_Name__as_on_Product_Packaging_, MAX(Flavour) AS Flavour, SUM(CAST(MRP AS NUMERIC)) AS MRP, SUM(CAST(MRP_Revised AS NUMERIC)) AS MRP_Revised,sku_details_Size FROM `beastlife-wh-474411.maplemonk.MasterCatalogue` GROUP BY 1,2,3,4,5,6,7,8,12 ), base AS ( SELECT f.channel_order_id, f.awb, f.courier, zone, d.Order_Date, EXTRACT(HOUR FROM d.order_time) AS hour, f.order_status, SAFE.PARSE_DATETIME( \'%Y-%m-%d %H:%M:%S\', COALESCE(NULLIF(TRIM(f.picked_up_date), \'\'), NULLIF(TRIM(p.picked_up_date), \'\')) ) AS pickup_dt, awb_assign_date, f.delivered_date, f.first_out_for_delivery_date, f.delivered_date AS delivered_dt, SAFE_CAST(NULLIF(TRIM(f.first_out_for_delivery_date), \'\') AS DATETIME) AS ofd_dt, pickup_scheduled_date, pickup_location, f.payment_method, rto_delivered_date, rto_initiated_date, CASE WHEN zone = \'z_a\' AND UPPER(f.courier) LIKE \'%NDD%\' THEN 1 WHEN zone = \'z_b\' AND UPPER(f.courier) LIKE \'%NDD%\' THEN 1 WHEN zone = \'z_a\' AND UPPER(f.courier) LIKE \'%SURFACE%\' THEN 2 WHEN zone = \'z_b\' THEN 3 WHEN zone = \'z_c\' THEN 5 WHEN zone = \'z_d\' THEN 7 WHEN zone = \'z_e\' THEN 9 ELSE NULL END AS tat_limit_days, CASE COALESCE(shippingPackageStatus, u.ORDER_STATUS) WHEN \'DELIVERED\' THEN \'DISPATCHED\' WHEN \'RETURN_EXPECTED\' THEN \'DISPATCHED\' WHEN \'SHIPPED\' THEN \'DISPATCHED\' WHEN \'RETURN_ACKNOWLEDGED\' THEN \'DISPATCHED\' WHEN \'MANIFESTED\' THEN \'DISPATCHED\' WHEN \'DISPATCHED\' THEN \'DISPATCHED\' WHEN \'RETURNED\' THEN \'RETURNED\' WHEN \'CANCELLED\' THEN \'CANCELLED\' WHEN \'ALTERNATE_ACCEPTED\' THEN \'ALTERNATE_ACCEPTED\' WHEN \'PACKED\' THEN \'PACKED\' WHEN \'READY_TO_SHIP\' THEN \'READY_TO_SHIP\' WHEN \'PICKED\' THEN \'PICKED\' WHEN \'PICKING\' THEN \'PICKING\' WHEN \'CREATED\' THEN \'CREATED\' WHEN \'FULFILLABLE\' THEN \'UNFULFILLABLE\' WHEN \'UNFULFILLABLE\' THEN \'UNFULFILLABLE\' ELSE \'UNKNOWN\' END AS Consolidated_Status FROM `maplemonk.beastlife_shiprocket_fact_items_current` f LEFT JOIN p ON f.awb = p.awb LEFT JOIN u ON f.channel_order_id = u.reference_code LEFT JOIN d ON f.channel_order_id = d.ordeR_name ), tat AS ( SELECT b.*, DATE(b.pickup_dt) AS pickup_date, CASE WHEN UPPER(b.order_status) LIKE \'%RTO%\' THEN NULL ELSE DATE_DIFF( COALESCE(DATE(b.delivered_dt), CURRENT_DATE(\'Asia/Kolkata\')), DATE(b.pickup_dt), DAY ) END AS TAT_Days, DATE_DIFF(DATE(b.ofd_dt), DATE(b.pickup_dt), DAY) AS FASR_Days, DATE_DIFF(DATE(b.delivered_dt), DATE(b.pickup_dt), DAY) AS Delivered_Days FROM base b ) SELECT calendar.*, t.channel_order_id, t.awb, t.courier, t.zone, t.Order_Date, t.hour, t.order_status, t.pickup_date AS picked_up_date, t.awb_assign_date, t.delivered_date, t.first_out_for_delivery_date, t.pickup_scheduled_date, t.pickup_location, t.payment_method, t.rto_delivered_date, t.rto_initiated_date, EXTRACT(HOUR FROM t.pickup_dt) AS PickedUp_hour, t.TAT_Days, t.tat_limit_days AS TAT_Limit_Days, CASE WHEN UPPER(t.order_status) LIKE \'%RTO%\' THEN NULL WHEN t.pickup_date IS NULL THEN \'No Pickup Date\' WHEN t.tat_limit_days IS NULL THEN \'TAT Not Defined\' WHEN t.TAT_Days > t.tat_limit_days THEN \'TAT Breached\' ELSE \'Not Breached\' END AS TAT_Breach_Status, t.TAT_Days - t.tat_limit_days AS Days_Beyond_TAT, CASE WHEN t.TAT_Days - t.tat_limit_days IS NULL THEN NULL WHEN t.TAT_Days - t.tat_limit_days < 0 THEN \'Within TAT (<0)\' WHEN t.TAT_Days - t.tat_limit_days = 0 THEN \'On TAT (0)\' WHEN t.TAT_Days - t.tat_limit_days = 1 THEN \'1 Day\' WHEN t.TAT_Days - t.tat_limit_days <= 7 THEN CONCAT(CAST(t.TAT_Days - t.tat_limit_days AS STRING), \' Days\') ELSE \'>7 Days\' END AS Ageing_Bucket, t.FASR_Days, t.Consolidated_Status FROM tat t LEFT JOIN calendar ON t.pickup_date = calendar.event_date where t.order_status!=\"RETURN DELIVERED\"",
                    "transaction": true
                }
            ) }}
